1	const errors = require('@tryghost/errors');
2	const tpl = require('@tryghost/tpl');
3	const models = require('../../models');
4	
5	const messages = {
6	    snippetNotFound: 'Snippet not found.',
7	    snippetAlreadyExists: 'Snippet already exists.'
8	};
9	
10	/** @type {import('@tryghost/api-framework').Controller} */
11	const controller = {
12	    docName: 'snippets',
13	
14	    browse: {
15	        headers: {
16	            cacheInvalidate: false
17	        },
18	        options: [
19	            'limit',
20	            'order',
21	            'page',
22	            'formats',
23	            'filter'
24	        ],
25	        permissions: true,
26	        validation: {
27	            options: {
28	                formats: {
29	                    values: models.Snippet.allowedFormats
30	                }
31	            }
32	        },
33	        query(frame) {
34	            return models.Snippet.findPage(frame.options);
35	        }
36	    },
37	
38	    read: {
39	        headers: {
40	            cacheInvalidate: false
41	        },
42	        options: [
43	            'formats'
44	        ],
45	        data: [
46	            'id'
47	        ],
48	        permissions: true,
49	        async query(frame) {
50	            const model = await models.Snippet.findOne(frame.data, frame.options);
51	            if (!model) {
52	                throw new errors.NotFoundError({
53	                    message: tpl(messages.snippetNotFound)
54	                });
55	            }
56	
57	            return model;
58	        }
59	    },
60	
61	    add: {
62	        statusCode: 201,
63	        headers: {
64	            cacheInvalidate: false
65	        },
66	        options: [
67	            'formats'
68	        ],
69	        permissions: true,
70	        query(frame) {
71	            return models.Snippet.add(frame.data.snippets[0], frame.options)
72	                .catch((error) => {
73	                    if (error.code && error.message.toLowerCase().indexOf('unique') !== -1) {
74	                        throw new errors.ValidationError({message: tpl(messages.snippetAlreadyExists)});
75	                    }
76	
77	                    throw error;
78	                });
79	        }
80	    },
81	
82	    edit: {
83	        headers: {
84	            cacheInvalidate: false
85	        },
86	        options: [
87	            'id',
88	            'formats'
89	        ],
90	        validation: {
91	            options: {
92	                id: {
93	                    required: true
94	                }
95	            }
