const ghostBookshelf = require('./base');

const AuditLog = ghostBookshelf.Model.extend({
    tableName: 'actions', // Using actions table temporarily - should be 'audit_logs' after migration

    defaults() {
        return {
            actor_type: 'user'
        };
    },

    user() {
        return this.belongsTo('User', 'actor_id');
    }
}, {
    orderDefaultOptions: function orderDefaultOptions() {
        return {
            created_at: 'DESC'
        };
    },

    permittedOptions(methodName) {
        const options = ghostBookshelf.Model.permittedOptions.call(this, methodName);

        if (methodName === 'findPage') {
            return options.concat(['filter', 'order']);
        }

        return options;
    },

    async findPage(options = {}) {
        // Default to filtering only user actions for audit logs
        const filter = options.filter ? `${options.filter}+actor_type:user` : 'actor_type:user';
        return ghostBookshelf.Model.findPage.call(this, {...options, filter});
    }
});

module.exports = {
    AuditLog: ghostBookshelf.model('AuditLog', AuditLog)
};

const errors = require('@tryghost/errors');
const tpl = require('@tryghost/tpl');
const models = require('../../models');

const messages = {
    auditLogNotFound: 'Audit log not found.'
};

/** @type {import('@tryghost/api-framework').Controller} */
const controller = {
    docName: 'audit_logs',

    browse: {
        headers: {
            cacheInvalidate: false
        },
        options: [
            'limit',
            'page',
            'filter',
            'order',
            'include'
        ],
        permissions: true,
        query(frame) {
            return models.AuditLog.findPage(frame.options);
        }
    },

    read: {
        headers: {
            cacheInvalidate: false
        },
        options: [
            'include'
        ],
        data: [
            'id'
        ],
        permissions: true,
        async query(frame) {
            const model = await models.AuditLog.findOne(frame.data, frame.options);
            if (!model) {
                throw new errors.NotFoundError({
                    message: tpl(messages.auditLogNotFound)
                });
            }

            return model;
        }
    }
};

module.exports = controller;

