const assert = require('node:assert/strict');
const {agentProvider, fixtureManager, matchers} = require('../../utils/e2e-framework');
const {anyObjectId, anyISODateTime, anyContentVersion, anyEtag} = matchers;

const matchAuditLog = {
    id: anyObjectId,
    created_at: anyISODateTime
};

describe('Audit Logs API', function () {
    let agent;

    before(async function () {
        agent = await agentProvider.getAdminAPIAgent();
        await fixtureManager.init('posts');
        await agent.loginAsOwner();
    });

    it('Can browse audit logs', async function () {
        const {body} = await agent
            .get('audit_logs/')
            .expectStatus(200)
            .matchHeaderSnapshot({
                'content-version': anyContentVersion,
                etag: anyEtag
            });

        assert(body.audit_logs);
        assert(Array.isArray(body.audit_logs));
        assert(body.meta);
        assert(body.meta.pagination);

        // Verify structure of first audit log if exists
        if (body.audit_logs.length > 0) {
            const log = body.audit_logs[0];
            assert(log.id);
            assert(log.created_at);
        }
    });

    it('Can browse with pagination', async function () {
        const {body} = await agent
            .get('audit_logs/?limit=5&page=1')
            .expectStatus(200)
            .matchHeaderSnapshot({
                'content-version': anyContentVersion,
                etag: anyEtag
            });

        assert(body.audit_logs);
        assert(Array.isArray(body.audit_logs));
        assert(body.meta);
        assert(body.meta.pagination);
        assert(body.meta.pagination.limit === 5);
        assert(body.meta.pagination.page === 1);
    });

    it('Can read a single audit log by id', async function () {
        // First get a list to find an ID
        const browseRes = await agent
            .get('audit_logs/')
            .expectStatus(200);

        if (browseRes.body.audit_logs.length === 0) {
            this.skip();
        }

        const auditLogId = browseRes.body.audit_logs[0].id;

        const {body} = await agent
            .get(`audit_logs/${auditLogId}/`)
            .expectStatus(200)
            .matchHeaderSnapshot({
                'content-version': anyContentVersion,
                etag: anyEtag
            });

        assert(body.audit_logs);
        assert(Array.isArray(body.audit_logs));
        assert.equal(body.audit_logs.length, 1);
        assert.equal(body.audit_logs[0].id, auditLogId);
    });

    it('Returns 404 for non-existent audit log', async function () {
        await agent
            .get('audit_logs/000000000000000000000000/')
            .expectStatus(404)
            .matchHeaderSnapshot({
                'content-version': anyContentVersion,
                etag: anyEtag
            })
            .matchBodySnapshot({
                errors: [{
                    id: anyObjectId
                }]
            });
    });

    describe('Permissions', function () {
        it('Requires authentication', async function () {
            const unauthenticatedAgent = await agentProvider.getAdminAPIAgent();

            await unauthenticatedAgent
                .get('audit_logs/')
                .expectStatus(401);
        });

        it('Owner can browse audit logs', async function () {
            const ownerAgent = await agentProvider.getAdminAPIAgent();
            await ownerAgent.loginAsOwner();

            await ownerAgent
                .get('audit_logs/')
                .expectStatus(200);
        });

        it('Admin can browse audit logs', async function () {
            await fixtureManager.init('users:roles');
            const adminAgent = await agentProvider.getAdminAPIAgent();
            await adminAgent.loginAsAdmin();

            await adminAgent
                .get('audit_logs/')
                .expectStatus(200);
        });
    });

    describe('Filtering', function () {
        it('Can filter audit logs', async function () {
            const {body} = await agent
                .get('audit_logs/?filter=actor_type:user')
                .expectStatus(200);

            assert(body.audit_logs);
            assert(Array.isArray(body.audit_logs));
        });
    });

    describe('Ordering', function () {
        it('Can order audit logs by created_at DESC (default)', async function () {
            const {body} = await agent
                .get('audit_logs/')
                .expectStatus(200);

            assert(body.audit_logs);

            if (body.audit_logs.length > 1) {
                const firstDate = new Date(body.audit_logs[0].created_at);
                const secondDate = new Date(body.audit_logs[1].created_at);
                assert(firstDate >= secondDate, 'Audit logs should be ordered by created_at DESC');
            }
        });

        it('Can order audit logs by created_at ASC', async function () {
            const {body} = await agent
                .get('audit_logs/?order=created_at%20ASC')
                .expectStatus(200);

            assert(body.audit_logs);

            if (body.audit_logs.length > 1) {
                const firstDate = new Date(body.audit_logs[0].created_at);
                const secondDate = new Date(body.audit_logs[1].created_at);
                assert(firstDate <= secondDate, 'Audit logs should be ordered by created_at ASC');
            }
        });
    });
});

