const ghostBookshelf = require('./base');

const AuditLog = ghostBookshelf.Model.extend({
    tableName: 'actions', // Using actions table temporarily - should be 'audit_logs' after migration

    defaults() {
        return {
            actor_type: 'user'
        };
    },

    user() {
        return this.belongsTo('User', 'actor_id');
    }
}, {
    orderDefaultOptions: function orderDefaultOptions() {
        return {
            created_at: 'DESC'
        };
    },

    permittedOptions(methodName) {
        const options = ghostBookshelf.Model.permittedOptions.call(this, methodName);

        if (methodName === 'findPage') {
            return options.concat(['filter', 'order']);
        }

        return options;
    },

    async findPage(options = {}) {
        // Default to filtering only user actions for audit logs
        const filter = options.filter ? `${options.filter}+actor_type:user` : 'actor_type:user';
        return ghostBookshelf.Model.findPage.call(this, {...options, filter});
    }
});

module.exports = {
    AuditLog: ghostBookshelf.model('AuditLog', AuditLog)
};

