const errors = require('@tryghost/errors');
const tpl = require('@tryghost/tpl');
const models = require('../../models');

const messages = {
    auditLogNotFound: 'Audit log not found.'
};

/** @type {import('@tryghost/api-framework').Controller} */
const controller = {
    docName: 'audit_logs',

    browse: {
        headers: {
            cacheInvalidate: false
        },
        options: [
            'limit',
            'page',
            'filter',
            'order',
            'include'
        ],
        permissions: true,
        query(frame) {
            return models.AuditLog.findPage(frame.options);
        }
    },

    read: {
        headers: {
            cacheInvalidate: false
        },
        options: [
            'include'
        ],
        data: [
            'id'
        ],
        permissions: true,
        async query(frame) {
            const model = await models.AuditLog.findOne(frame.data, frame.options);
            if (!model) {
                throw new errors.NotFoundError({
                    message: tpl(messages.auditLogNotFound)
                });
            }

            return model;
        }
    }
};

module.exports = controller;

